import functools
def brute(h):
    n = len(h)
    @functools.lru_cache(None)
    def f(i):
        best = 1
        for d in (1, -1):
            j = i + d
            while 0 <= j < n and h[j] < h[i]: best = max(best, 1 + f(j)); j += d
        return best
    return max(f(i) for i in range(n))
def reach(h, i):
    n = len(h); c = 0
    for d in (1, -1):
        j = i + d
        while 0 <= j < n and h[j] < h[i]: c += 1; j += d
    return c
M = (20, 15, 17, 35, 25, 40, 12, 19, 13, 12)
result = brute(M)

